        self.virtual_ts_check_options.check_unknown_directives = options
            .as_ref()
            .and_then(|options| {
                options
                    .get("checkUnknownDirectives")
                    .or_else(|| options.get("strictTemplates"))
                    .and_then(Value::as_bool)
            })
            .unwrap_or(false);
